<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Holder\ConsentPurposeTitleAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeTitleAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ConsentPurposeTitleAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTitle returns null on a freshly created holder.
     */
    public function testTitleNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeTitleAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTitleAssigned());
        $this->assertNull($holder->getTitle());
    }
}
class ImplWithConsentPurposeTitleAttributeHolderUnitTest
{
    use ConsentPurposeTitleAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTitleRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTitle();
    }
}
